import java.util.Scanner;

public class Main {
    static final long MOD = 1000000007;

    static long readInput(Scanner sc) {
        long x = 0;
        boolean negative = false;
        char ch = sc.next().charAt(0);
        while (ch < '0' || ch > '9') {
            if (ch == '-') {
                negative = true;
            }
            ch = sc.next().charAt(0);
        }
        x = ch - '0';
        while (true) {
            if (!sc.hasNext()) break;
            ch = sc.next().charAt(0);
            if (ch < '0' || ch > '9') break;
            x = x * 10 + ch - '0';
        }
        return negative ? -x : x;
    }

    static long multiplyMod(long a, long b, long m) {
        long result = 0;
        a %= m;
        while (b > 0) {
            if ((b & 1) == 1) {
                result = (result + a) % m;
            }
            b >>= 1;
            a = (a + a) % m;
        }
        return result;
    }

    static long powerMod(long a, long b, long m) {
        long result = 1;
        a %= m;
        while (b > 0) {
            if ((b & 1) == 1) {
                result = multiplyMod(result, a, m);
            }
            b >>= 1;
            a = multiplyMod(a, a, m);
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long p = readInput(sc);
        long k = readInput(sc);
        long ret;
        if (k == 0) {
            ret = powerMod(p, p - 1, MOD);
        } else if (k == 1) {
            ret = powerMod(p, p, MOD);
        } else {
            long l = 1;
            long cur = k;
            while (cur != 1) {
                cur = (cur * k) % p;
                l++;
            }
            ret = powerMod(p, (p - 1) / l, MOD);
        }
        System.out.println(ret);
        sc.close();
    }
}
